/* handle table: the collaborator holds an int, never the target pointer */
struct fwd { void *target; const struct file_ops *ops; bool enabled; uint32_t gen; };

int h = fwd_grant(&slot, fd, &file_ops);      /* the forwarder the caller receives */
struct fwd *e = fwd_of(&slot, h);             /* NULL if revoked or stale */
if (!e || !e->enabled)
        return -EACCES;                        /* fail closed after revocation */
return e->ops->read(e->target, buf, n);
/* revoke: e->enabled = false; ++slot.gen;   -> every outstanding handle dies */
